 1	package deep
 2	
 3	import "fmt"
 4	
 5	// Route decides what to do with an event.
 6	func Route(events []Event, strict bool) []string {
 7		var out []string
 8		for _, ev := range events {
 9			switch ev.Kind {
10			case "message":
11				if ev.User != "" {
12					for _, part := range ev.Parts {
13						if part.Text != "" {
14							if strict && len(part.Text) > 400 {
15								out = append(out, "too long")
16								continue
17							}
18							out = append(out, fmt.Sprintf("%s: %s", ev.User, part.Text))
19						}
20					}
21				}
22			case "join":
23				out = append(out, ev.User+" joined")
24			default:
25				if strict {
26					out = append(out, "unknown event")
27				}
28			}
29		}
30		return out
31	}
32	
33	// Event is one line of chat.
34	type Event struct {
35		Kind  string
36		User  string
37		Parts []Part
38	}
39	
40	// Part is a piece of a message.
41	type Part struct {
42		Text string
43	}

